const visible=()=>state.catalog.filter(t=>(!moduleFilter||t.module===moduleFilter)&&`${t.title} ${t.code} ${t.module}`.toLowerCase().includes(query.toLowerCase()));
function historyTable(rows){return rows.length?`<div class="table-wrap"><table><thead><tr><th>Uruchomienie</th><th>Przeglądarka</th><th>Wynik</th><th>Data</th><th></th></tr></thead><tbody>${rows.map(run=>`<tr><td class="title">${esc(run.title)}<small>${esc(run.environment)} · ${run.results.length}/${run.total} zakończonych</small></td><td>${esc(run.browser)}</td><td>${badge(run.status)}</td><td>${esc(date(run.startedAt))}</td><td><button class="link" data-detail="${esc(run.id)}">Szczegóły →</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><strong>Jeszcze nie uruchamiano testów</strong>Wybierz scenariusze w katalogu. Tutaj pojawią się rzeczywiste wyniki.</div>';}
function runDetail(run){if(!run)return '';return `<article class="card run-detail"><div class="section-head"><div><span class="eyebrow">SZCZEGÓŁY URUCHOMIENIA</span><h2>${esc(run.title)}</h2></div>${badge(run.status)}</div><div class="run-summary"><p>${run.counts.passed} zaliczonych · ${run.counts.failed} błędnych · ${run.counts.skipped} pominiętych</p>${run.report?`<a href="${esc(run.report)}" target="_blank" rel="noopener">Raport Playwright ↗</a>`:''}</div><p class="notice">${run.results.length} z ${run.total} scenariuszy · ${esc(run.browser)} · ${esc(run.environment)}</p><progress max="${Math.max(1,run.total)}" value="${run.results.length}" aria-label="Postęp testów"></progress>${run.results.length?`<div class="table-wrap"><table><thead><tr><th>Scenariusz</th><th>Wynik</th><th>Czas</th></tr></thead><tbody>${run.results.map(result=>`<tr><td>${esc(result.title)}</td><td>${badge(result.status)}${(result.dataErrors||[]).map(d=>`<p><b>${esc(d.label)}</b><br>${esc(d.summary)}<br>${esc(d.suggestion)}<br>${esc(d.qualification)}</p>`).join('')}${result.warnings?.length?`<small>${result.warnings.length} uwag — zobacz raport</small>`:''}</td><td>${(result.duration/1000).toFixed(1)} s</td></tr>`).join('')}</tbody></table></div>`:''}<h3 class="section-head">Log uruchomienia</h3><pre tabindex="0">${esc(run.logs.join('\n')||'Oczekiwanie na komunikaty Playwright…')}</pre></article>`;}
function render(){if(!state)return;const current=view();const titles={debugger:['Debugger testów','Podgląd przeglądarki, opisane kroki i wyniki.'],overview:['Przegląd','Twój warsztat testów panelu Sylius.'],tests:['Katalog testów','Wybierz scenariusze i uruchom je w wybranej przeglądarce.'],history:['Historia uruchomień','Wyniki, logi i raporty z rzeczywistych wykonań.'],settings:['Konfiguracja','Lokalne środowisko i połączenie z Centrum testów.']};const title=titles[current]||titles.overview;$('#heading').textContent=title[0];$('#subtitle').textContent=title[1];$('#test-count').textContent=state.catalog.length;
 document.querySelectorAll('[data-view]').forEach(link=>link.classList.toggle('active',link.dataset.view===current));
 $('#warnings').innerHTML=state.configuration.missing.length?`<div class="warning">Uzupełnij lokalny plik .env: ${esc(state.configuration.missing.join(', '))}. <a href="#settings">Zobacz konfigurację →</a></div>`:'';
 if(linkedTests.length)$('#warnings').innerHTML+=`<div class="callout">Zgłoszenie #${esc(linkedQuery.get('issue')||'—')}: wybrano ${selected.size} scenariuszy. Czekają na uruchomienie.${linkedMissing.length?' Nie znaleziono: '+esc(linkedMissing.join(', '))+'. Uruchomienie jest zablokowane.':''}</div>`;
 const content=$('#content'),active=state.history.find(run=>run.id===state.active);
 if(current==='debugger'){if(!content.querySelector('#cms-debugger-frame'))content.innerHTML='<iframe id="cms-debugger-frame" title="Debugger testów CMS" src="/debugger/"></iframe>';return;}
 if(current==='tests'){content.innerHTML=`<div class="test-layout"><div><div class="toolbar"><input id="search" type="search" aria-label="Szukaj scenariusza" placeholder="Szukaj po nazwie lub pliku…" value="${esc(query)}"><select id="module" aria-label="Rodzaj scenariusza"><option value="">Wszystkie scenariusze</option>${[...new Set(state.catalog.map(t=>t.module))].map(m=>`<option ${m===moduleFilter?'selected':''}>${esc(m)}</option>`).join('')}</select></div><div class="toolbar"><button id="select-upgrade" class="secondary">Zestaw po aktualizacji</button><button id="select-visible" class="secondary">Zaznacz widoczne</button><button id="clear-selection" class="secondary">Wyczyść wybór</button><span class="count">${visible().length} widocznych · ${selected.size} wybranych</span></div><div class="table-wrap"><table><thead><tr><th></th><th>Scenariusz</th><th>Rodzaj</th></tr></thead><tbody>${visible().map(test=>`<tr><td><input type="checkbox" data-test="${esc(test.id)}" aria-label="Zaznacz ${esc(test.title)}" ${selected.has(test.id)?'checked':''}></td><td class="test-name">${esc(test.title)}<small>${esc(test.file)}</small><button type="button" class="secondary" data-edit-scenario="${esc(test.id)}">Opis / edycja</button></td><td><span class="badge auto">${esc(test.module)}</span></td></tr>`).join('')}</tbody></table></div>${visible().length?'':'<div class="empty">Brak scenariuszy pasujących do wyszukiwania.</div>'}</div><aside class="card run-options"><span class="eyebrow">NOWE URUCHOMIENIE</span><h2>Sprawdź CMS</h2><label>Przeglądarka<select id="browser" aria-label="Przeglądarka">${state.browsers.map(b=>`<option ${b===browser?'selected':''}>${b}</option>`).join('')}</select></label><label class="check"><input id="headed" type="checkbox" ${headed?'checked':''}> Pokaż okno przeglądarki</label><p class="notice">W otwartym oknie zobaczysz nazwę testu, aktualny etap i wykonywaną czynność. Podgląd nie pokazuje wpisywanych haseł.</p><label class="check"><input id="strict-assets" type="checkbox" ${strictAssets?'checked':''}> Sprawdź także obrazy i zasoby</label><p class="notice">Opcja zasobów dotyczy zestawu „Widoki po aktualizacji”.</p><p class="notice">Środowisko: <strong>${esc(state.configuration.target||'Nieskonfigurowane')}</strong><br>Testy uruchamiają się po zalogowaniu do CMS.</p><button id="run" class="primary" ${!selected.size||state.active||state.configuration.missing.length||launching?'disabled':''}>▷ Uruchom wybrane (${selected.size})</button><p class="notice">${state.active?'Trwa uruchomienie. Poczekaj na wynik.':'Wybierz pojedynczy scenariusz lub cały zestaw.'}</p></aside></div>${runDetail(active||state.history.find(r=>r.id===detailId))}`;return;}
 if(current==='history'){content.innerHTML=historyTable(state.history)+runDetail(state.history.find(r=>r.id===detailId)||active);return;}
 if(current==='settings'){content.innerHTML=`<div class="two-col"><article class="card"><span class="eyebrow">ŚRODOWISKO CMS</span><h2>Dane logowania</h2><p class="notice">Uzupełnij plik <code>.env</code> w folderze projektu. Po zmianie konfiguracji uruchom ponownie panel.</p><div class="table-wrap"><table><thead><tr><th>Zmienna</th><th>Stan</th></tr></thead><tbody>${['BASE_URL','USER_NAME','PASSWORD'].map(key=>`<tr><td>${key}</td><td>${state.configuration.missing.includes(key)?'<span class="badge BLOCKED">Do uzupełnienia</span>':'<span class="badge PASS">Ustawiona</span>'}</td></tr>`).join('')}</tbody></table></div><p class="notice">Adres środowiska: ${esc(state.configuration.target||'Brak adresu')}. Hasła i tokeny pozostają w lokalnej konfiguracji.</p></article><article class="card"><span class="eyebrow">WSPÓLNY WARSZTAT QA</span><h2>Centrum testów</h2><p class="notice">Katalog i historia CMS są dostępne w Centrum. Tam możesz powiązać scenariusze i raporty ze zgłoszeniem Redmine, zapisać sprawdzenie ręczne i dodać dowody.</p><a class="primary collection-download" href="http://127.0.0.1:4180/#projects" target="_blank" rel="noopener">Otwórz Centrum testów ↗</a><p class="notice">Panel CMS: 127.0.0.1:4181<br>Centrum: 127.0.0.1:4180</p></article></div>`;return;}
 const latest=state.history.find(r=>r.status!=='RUNNING');content.innerHTML=`<div class="stats"><div class="stat"><label>Scenariusze CMS</label><strong>${state.catalog.length}</strong><small>Katalog odczytywany z projektu</small></div><div class="stat"><label>Przeglądarki</label><strong>${state.browsers.length}</strong><small>Chromium, Firefox i WebKit</small></div><div class="stat"><label>Zapisane uruchomienia</label><strong>${state.history.length}</strong><small>Historia na Twoim komputerze</small></div><div class="stat"><label>Ostatni wynik</label><strong>${latest?badge(latest.status):'—'}</strong><small>${latest?esc(date(latest.startedAt)):'Czeka na pierwsze wykonanie'}</small></div></div><article class="card intro"><span class="eyebrow">KSIĘGARNIA CMS</span><h2>Od scenariusza do potwierdzonego wyniku.</h2><p class="notice">Sprawdzaj produkty, zamówienia, klientów, promocje i ustawienia Syliusa. Wybierz testy w katalogu, obserwuj postęp i wróć do raportu w Centrum testów.</p><div class="actions"><button id="select-upgrade" class="primary">Testy po aktualizacji →</button><a class="secondary collection-download" href="#tests">Wszystkie testy →</a><a class="secondary collection-download" href="#history">Historia uruchomień →</a></div></article>${runDetail(active)}<div class="section-head"><h2>Ostatnie uruchomienia</h2><a href="#history">Pełna historia →</a></div>${historyTable(state.history.slice(0,5))}`;
}
const linkedQuery=new URLSearchParams(location.search),linkedTests=[...new Set(linkedQuery.getAll('test'))];
let linkedApplied=false,linkedMissing=[];
function applyLinkedSelection(){
 if(linkedApplied||!linkedTests.length)return;
 linkedApplied=true;
 selected=new Set(linkedTests.filter(id=>state.catalog.some(t=>t.id===id)));
 const missing=linkedTests.filter(id=>!state.catalog.some(t=>t.id===id));linkedMissing=missing;
 location.hash='tests';
 if(missing.length)toast('Nie znaleziono testów: '+missing.join(', ')+'. Sprawdź powiązania zgłoszenia.');
 else toast('Zgłoszenie #'+(linkedQuery.get('issue')||'—')+': wybrano '+selected.size+' scenariuszy. Czekają na uruchomienie.');
}
async function load({poll=false}={}){const data=await api('/api/state');const changed=JSON.stringify(data)!==JSON.stringify(state);state=data;applyLinkedSelection();if(!poll||changed){if(poll&&['search','module','browser','headed','strict-assets'].includes(document.activeElement?.id))return;render();}}
$('#refresh').addEventListener('click',()=>load().catch(e=>toast(e.message)));
window.addEventListener('hashchange',render);
document.addEventListener('input',event=>{if(event.target.id==='search'){const position=event.target.selectionStart;query=event.target.value;render();$('#search').focus();$('#search').setSelectionRange(position,position);}});
document.addEventListener('change',event=>{const element=event.target;if(element.dataset.test){element.checked?selected.add(element.dataset.test):selected.delete(element.dataset.test);render();}if(element.id==='module'){moduleFilter=element.value;render();}if(element.id==='browser')browser=element.value;if(element.id==='headed')headed=element.checked;if(element.id==='strict-assets')strictAssets=element.checked;});
document.addEventListener('click',async event=>{const element=event.target.closest('button');if(!element)return;try{if(element.dataset.editScenario){await editScenarioDescription(element.dataset.editScenario);return;}if(element.id==='select-upgrade'){query='';moduleFilter='Widoki po aktualizacji';selected=new Set(state.catalog.filter(t=>t.module===moduleFilter).map(t=>t.id));location.hash='tests';render();}if(element.id==='select-visible'){visible().forEach(t=>selected.add(t.id));render();}if(element.id==='clear-selection'){selected.clear();render();}if(element.dataset.detail){detailId=element.dataset.detail;location.hash='history';render();$('.run-detail')?.scrollIntoView({behavior:'smooth'});}if(element.id==='run'){if(linkedMissing.length)throw new Error('Nie znaleziono wszystkich testów ze zgłoszenia. Sprawdź powiązania przed uruchomieniem.');launching=true;render();try{const run=await api('/api/run',{testIds:[...selected],browser,headed,strictAssets});detailId=run.id;toast('Testy zostały uruchomione.');await load();}finally{launching=false;render();}}}catch(error){toast(error.message);}});
load().catch(error=>{$('#content').textContent='Nie udało się wczytać panelu: '+error.message;});
setInterval(()=>load({poll:true}).catch(()=>{}),1500);

/* QA_GUIDE_START */
// Wspólna instrukcja obsługi. Adapter projektu dostarcza rzeczywiste dane testu.
function installQaGuide(config) {
  const escape = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const list = values => `<ol>${values.filter(Boolean).map(value => `<li>${escape(value)}</li>`).join('')}</ol>`;
  const section = (title, content) => `<section><h3>${title}</h3>${content}</section>`;
  const legend = `<dl class="qa-guide-legend"><dt>PASS / Zaliczone</dt><dd>Wykonane kontrole spełniły oczekiwania. Otwórz raport i potwierdź, że zawiera wybrany test.</dd><dt>FAIL / Niezaliczone</dt><dd>Kontrola nie przeszła lub wystąpił problem z jej wykonaniem. Odczytaj przyczynę; sam czerwony wynik nie rozstrzyga, czy winna jest aplikacja, dane czy połączenie.</dd><dt>SKIP / Pominięte</dt><dd>Nie sprawdzono tego warunku. To nie jest potwierdzenie poprawności.</dd><dt>BLOCKED / Zablokowane</dt><dd>Brakuje warunku potrzebnego do wykonania. Uzupełnij wskazane dane lub dostęp.</dd><dt>INCOMPLETE / Niepełne</dt><dd>Sprawdzono część zakresu; pozostałe warunki nadal wymagają wykonania.</dd></dl>`;
  const dialog = document.createElement('dialog');
  dialog.className = 'qa-guide-dialog';
  dialog.setAttribute('aria-labelledby', 'qa-guide-title');
  document.body.append(dialog);
  let returnFocus;
  dialog.addEventListener('click', event => { if (event.target.closest('[data-guide-close]')) dialog.close(); });
  dialog.addEventListener('close', () => { if (returnFocus?.isConnected) returnFocus.focus(); });
  function show(test, opener) {
    returnFocus = opener;
    const manual = test.type === 'manual';
    const steps = Array.isArray(test.steps) ? test.steps : test.steps ? [test.steps] : [];
    const expected = Array.isArray(test.expected) ? test.expected : test.expected ? [test.expected] : [];
    const effect = test.effect || config.effect;
    const actions = manual
      ? ['Przeczytaj warunki i oczekiwany wynik poniżej.', 'Wykonaj opisane kroki w testowanej aplikacji.', 'W Centrum wybierz „Zapisz wynik ręczny”, wpisz rzeczywisty rezultat i dołącz dowody. Zapisz wynik zgodny z obserwacją.']
      : test.actions || config.actions;
    dialog.innerHTML = `<div class="qa-guide-head"><div><small>INSTRUKCJA TESTU · ${escape(config.name)}</small><h2 id="qa-guide-title">${escape(test.title)}</h2></div><button type="button" class="secondary" data-guide-close>Zamknij</button></div>`
      + section('1. Co sprawdzamy?', `<p>${escape(test.purpose || test.title)}</p>${test.scope ? `<p>${escape(test.scope)}</p>` : ''}`)
      + section('2. Co przygotować?', list(test.prepare || config.prepare))
      + section('3. Co kliknąć i co się stanie?', list(actions) + `<p class="qa-guide-effect"><strong>Wpływ na dane:</strong> ${escape(effect)}</p>`)
      + section(manual ? '4. Kroki do wykonania ręcznie' : '4. Co zrobi automat?', (manual ? '' : '<p>Po uruchomieniu poniższe czynności wykonuje program. Nie musisz samodzielnie wysyłać zapytań ani klikać w testowanej aplikacji.</p>') + (steps.length ? list(steps) : `<p>Szczegółowe kroki tego przypadku nie zostały jeszcze opisane w katalogu. Sprawdź zakres w dokumentacji projektu przed uruchomieniem; ta karta nie zastępuje pełnego opisu testu.</p>`))
      + section('5. Jakiego wyniku oczekiwać?', expected.length ? list(expected) : `<p>Automat ocenia warunki dotyczące scenariusza „${escape(test.title)}”. Katalog nie zawiera osobnego, pełnego opisu oczekiwanego rezultatu. Nie potwierdzaj całej funkcjonalności wyłącznie na podstawie nazwy testu.</p>`)
      + section('6. Gdzie jest wynik i co zrobić dalej?', `<p>${escape(test.result || config.result)}</p>${legend}<p>Do zgłoszenia przypnij raport z tego uruchomienia, wskaż faktycznie wykonane ID testów, środowisko i wersję aplikacji. Dla błędu opisz oczekiwany i rzeczywisty rezultat. Samo dodanie testu do zgłoszenia nie potwierdza poprawki.</p>`)
      + `<div class="qa-guide-foot"><p>Ta instrukcja nie uruchamia testu ani nie zmienia wyboru.</p><button type="button" class="secondary" data-guide-close>Wróć do panelu</button></div>`;
    dialog.showModal();
  }
  const intro = document.createElement('details');
  intro.className = 'qa-guide-intro';
  intro.innerHTML = `<summary>Pierwszy raz tutaj? Jak wybrać test i odczytać wynik</summary><div class="qa-guide-intro-body"><h3>${escape(config.name)} — od czego zacząć</h3>${list(config.intro)}<h3>Co oznacza wynik?</h3>${legend}<p><strong>Słownik:</strong> scenariusz = jeden opisany przypadek; zestaw = grupa testów; środowisko = adres sprawdzanej aplikacji; API = sprawdzanie poprzez zapytania zamiast klikania w przeglądarce; raport = zapis przebiegu i dowody.</p><p>Przy testach wybierz „Jak wykonać test?”, aby poznać przygotowanie, zakres, wpływ na dane i dalsze kroki.</p></div>`;
  const main = document.querySelector('main');
  const header = main?.querySelector(':scope > header');
  if (header) header.after(intro); else main?.prepend(intro);
  function button(test, host) {
    if (!host || host.querySelector(':scope > [data-qa-guide]')) return;
    const b = document.createElement('button');
    b.type = 'button'; b.className = 'secondary qa-guide-button'; b.dataset.qaGuide = 'true';
    b.textContent = 'Jak wykonać test?';
    b.setAttribute('aria-label', 'Jak wykonać test: ' + test.title);
    b.addEventListener('click', event => { event.preventDefault(); event.stopPropagation(); show(test, b); });
    host.append(b);
  }
  let pending = false;
  function refresh() {
    pending = false;
    config.decorate(button);
    const authorFields = document.querySelector('#modal[open] #fields');
    if (authorFields && document.querySelector('#dialog-title')?.textContent === 'Nowy test ręczny' && !authorFields.querySelector('.qa-guide-author')) {
      const note = document.createElement('p');
      note.className = 'qa-guide-effect qa-guide-author';
      note.textContent = 'Napisz instrukcję dla osoby, która pierwszy raz widzi aplikację: gdzie wejść, jakie dane przygotować, co kolejno kliknąć i jaki komunikat lub zapis ma się pojawić. Opisz również wpływ na dane i co posprzątać po próbie. Oczekiwany wynik podaj konkretnie, np. „Zapis jest zablokowany, a nowe zamówienie nie powstaje”.';
      authorFields.prepend(note);
    }
    for (const control of document.querySelectorAll(config.launchSelector || '[data-no-launch-control]')) {
      if (control.closest('.qa-guide-dialog')) continue;
      let note = control.parentElement.querySelector(':scope > .qa-guide-before-run');
      if (!note) { note = document.createElement('p'); note.className = 'qa-guide-before-run'; control.after(note); }
      const text = config.launchNote();
      if (note.textContent !== text) note.textContent = text;
    }
  }
  function queue() { if (!pending) { pending = true; setTimeout(refresh, 30); } }
  const observer = new MutationObserver(records => { if (records.some(record => !record.target.closest?.('.qa-guide-dialog,.qa-guide-intro,.qa-guide-before-run,.qa-guide-button'))) queue(); });
  if (main) observer.observe(main, {childList:true,subtree:true});
  document.addEventListener('change', queue);
  document.addEventListener('click', queue);
  refresh();
}

